/**
 * Session event storage types and schemas.
 *
 * Provides JSONL-based event storage for agent sessions with:
 * - Session metadata tracking
 * - Append-only event logs
 * - Integration with kspec commit boundaries
 */

import { z } from "zod";

// ─── Session Status ──────────────────────────────────────────────────────────

/**
 * Session status enum.
 * - active: Session is in progress
 * - completed: Session ended normally
 * - abandoned: Session ended without explicit close
 * - timed_out: Session ended due to timeout
 * - failed: Session ended due to an error
 *
 * AC: @session-model-evolution ac-3
 */
export const SessionStatusSchema = z.enum(["active", "completed", "abandoned", "timed_out", "failed"]);
export type SessionStatus = z.infer<typeof SessionStatusSchema>;

// ─── Session Metadata ────────────────────────────────────────────────────────

/**
 * Trigger source enum — what caused this agent session to be dispatched.
 * - manual: Started manually by user
 * - task.in_progress: Dispatched because a task is already in progress
 * - task.ready: Dispatched because a task became ready
 * - task.needs_work: Dispatched because a task needs work (fix cycle)
 * - task.pending_review: Dispatched for PR review
 * - legacy: Old ralph sessions without explicit trigger
 *
 * AC: @session-model-evolution ac-1, ac-2
 */
export const SessionTriggerSchema = z.enum([
  "manual",
  "task.in_progress",
  "task.ready",
  "task.needs_work",
  "task.pending_review",
  "legacy",
]);

export type SessionTrigger = z.infer<typeof SessionTriggerSchema>;

/**
 * Session metadata stored in session.yaml.
 * AC-5: includes task_id (optional), agent_type, status, started_at, ended_at
 */
export const SessionMetadataSchema = z.object({
  /** Session ULID */
  id: z.string(),

  /** Optional task being worked on */
  task_id: z.string().optional(),

  /** Type of agent running the session */
  agent_type: z.string(),

  /**
   * Reference to the agent definition that dispatched this session.
   * For legacy sessions without this field, defaults to agent_type value.
   * AC: @session-model-evolution ac-1, ac-2
   */
  agent_id: z.string().optional(),

  /**
   * Trigger source — what caused this session to be dispatched.
   * For legacy sessions without this field, defaults to "legacy".
   * AC: @session-model-evolution ac-1, ac-2
   */
  trigger: SessionTriggerSchema.optional(),

  /** Current session status */
  status: SessionStatusSchema,

  /** When session started (ISO 8601) */
  started_at: z.string().datetime(),

  /** When session ended (ISO 8601) - only set when status != 'active' */
  ended_at: z.string().datetime().optional(),

  /** Whether end-loop has been requested for this session */
  end_requested: z.boolean().optional(),

  /** Reason for end-loop request */
  end_reason: z.string().optional(),

  /** Reason for session close (normal exit, signal, error) */
  close_reason: z.string().optional(),
});

export type SessionMetadata = z.infer<typeof SessionMetadataSchema>;

/**
 * Input for creating a new session.
 */
export const SessionMetadataInputSchema = SessionMetadataSchema.omit({
  status: true,
  started_at: true,
  ended_at: true,
}).extend({
  status: SessionStatusSchema.optional(),
  started_at: z.string().datetime().optional(),
});

export type SessionMetadataInput = z.infer<typeof SessionMetadataInputSchema>;

// ─── Event Types ─────────────────────────────────────────────────────────────

/**
 * Supported event types for session tracking.
 *
 * agent.* events are emitted by the new agent runtime:
 * - agent.dispatched: Agent was dispatched for a task
 * - agent.started: Agent started work on a task
 * - agent.completed: Agent completed work (with structured outcome)
 * - agent.failed: Agent failed (error or crash)
 * - agent.timeout: Agent exceeded timeout limit
 *
 * AC: @session-model-evolution ac-4
 */
export const EventTypeSchema = z.enum([
  "session.start",
  "session.update",
  "iteration.timeout",
  "session.end",
  "session.wrapup",
  "prompt.sent",
  "tool.call",
  "tool.result",
  "note",
  "agent.dispatched",
  "agent.started",
  "agent.completed",
  "agent.failed",
  "agent.timeout",
]);

export type EventType = z.infer<typeof EventTypeSchema>;

// ─── Session Event ───────────────────────────────────────────────────────────

/**
 * A single event in the session log.
 * AC-2: Events include ts and seq auto-assigned on append.
 */
export const SessionEventSchema = z.object({
  /** Unix timestamp in milliseconds (auto-assigned) */
  ts: z.number(),

  /** Sequence number in session (auto-assigned, 0-indexed) */
  seq: z.number().int().nonnegative(),

  /** Event type */
  type: EventTypeSchema,

  /** Session this event belongs to */
  session_id: z.string(),

  /** Optional trace ID for correlation */
  trace_id: z.string().optional(),

  /** Type-specific event payload */
  data: z.unknown(),
});

export type SessionEvent = z.infer<typeof SessionEventSchema>;

/**
 * Input for appending an event (without auto-assigned fields).
 */
export const SessionEventInputSchema = SessionEventSchema.omit({
  ts: true,
  seq: true,
}).extend({
  ts: z.number().optional(),
  seq: z.number().int().nonnegative().optional(),
});

export type SessionEventInput = z.infer<typeof SessionEventInputSchema>;

// ─── Task Budget ────────────────────────────────────────────────────────────

/**
 * Task budget state stored in .kspec/sessions/{id}/budget.json.
 *
 * Budget lives on LOCAL filesystem (not shadow branch) to avoid contention
 * between ralph and spawned agents. Single-writer guarantee: ralph resets
 * only between iterations (agent not running), agent is only writer during
 * its turn.
 *
 * AC: @session-creation-and-env-injection ac-budget
 * AC: @session-creation-and-env-injection ac-budget-local
 * AC: @task-budget-enforcement ac-atomic-write
 */
export const TaskBudgetSchema = z.object({
  /** Maximum tasks that can be started per cycle/iteration */
  max_per_cycle: z.number().int().positive(),

  /** Number of tasks started in current cycle */
  started_this_cycle: z.number().int().nonnegative(),
});

export type TaskBudget = z.infer<typeof TaskBudgetSchema>;

/**
 * API Response Types
 *
 * Shared types for REST API responses between daemon and web-ui.
 * These types define the contract for HTTP endpoints.
 */

/**
 * Common paginated response wrapper
 * AC: @api-contract ac-4
 */
export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  offset: number;
  limit: number;
}

/**
 * Standard error response
 * AC: @api-contract ac-22, ac-23, ac-24
 */
export interface ErrorResponse {
  error: string;
  message?: string;
  suggestion?: string;
  details?: Array<{ field: string; message: string }>;
  current?: string;
  valid_transitions?: string[];
}

/**
 * Task summary for list endpoints
 * AC: @api-contract ac-2
 */
export interface TaskSummary {
  _ulid: string;
  slugs: string[];
  title: string;
  type: string;
  status: string;
  priority: number;
  spec_ref?: string;
  tags: string[];
  depends_on: string[];
  automation?: string;
  created_at: string;
  started_at?: string;
  notes_count: number;
  todos_count?: number;
  automation?: string;
}

/**
 * Full task with notes and todos
 * AC: @api-contract ac-5
 * AC: @ui-task-board ac-3 — description, plan_ref, session_ref for detail modal
 */
export interface TaskDetail extends TaskSummary {
  description?: string;
  derivation?: string;
  blocked_by: string[];
  depends_on: string[];
  context: string[];
  vcs_refs: string[];
  plan_ref?: string;
  session_ref?: string;
  notes: Note[];
  todos?: Todo[];
  notes_count: number;
  todos_count?: number;
}

/**
 * Task note
 */
export interface Note {
  _ulid: string;
  created_at: string;
  author: string;
  content: string;
  supersedes?: string;
}

/**
 * Task todo
 * Matches TodoSchema: id, text, done, done_at, added_at, added_by, promoted_to
 */
export interface Todo {
  id: number;
  text: string;
  done: boolean;
  done_at?: string;
  added_at: string;
  added_by?: string;
  promoted_to?: string;
}

/**
 * Spec item summary for list endpoints
 * AC: @api-contract ac-8
 */
export interface ItemSummary {
  _ulid: string;
  slugs: string[];
  title: string;
  type: string;
  status?: string;
  tags: string[];
  parent?: string;
  created_at: string;
}

/**
 * Full spec item with ACs and traits
 * AC: @api-contract ac-10
 */
export interface ItemDetail extends ItemSummary {
  description?: string;
  acceptance_criteria: AcceptanceCriterion[];
  traits: string[];
  depends_on: string[];
  priority?: number;
}

/**
 * Acceptance criterion
 */
export interface AcceptanceCriterion {
  _ulid: string;
  given: string;
  when: string;
  then: string;
  /** Test coverage status: true=covered, false=not covered, undefined=unknown */
  covered?: boolean;
}

/**
 * Inbox item
 * AC: @api-contract ac-12
 */
export interface InboxItem {
  _ulid: string;
  text: string;
  tags: string[];
  added_by: string;
  created_at: string;
}

/**
 * Session context
 * AC: @api-contract ac-15
 */
export interface SessionContext {
  focus?: string;
  threads: string[];
  open_questions: string[];
  updated_at: string;
}

/**
 * Agent definition
 * AC: @api-contract ac-16
 */
export interface Agent {
  _ulid: string;
  slugs: string[];
  role: string;
  status: string;
  capabilities: string[];
  constraints: string[];
}

/**
 * Workflow definition
 * AC: @api-contract ac-17
 */
export interface Workflow {
  _ulid: string;
  slugs: string[];
  name: string;
  steps: WorkflowStep[];
}

/**
 * Workflow step
 */
export interface WorkflowStep {
  _ulid: string;
  type: 'action' | 'check' | 'decision';
  content: string;
}

/**
 * Observation
 * AC: @api-contract ac-18
 */
export interface Observation {
  _ulid: string;
  type: 'friction' | 'success' | 'question' | 'idea';
  content: string;
  context?: string;
  created_at: string;
  resolved?: boolean;
  resolution?: string;
}

/**
 * Plan summary for list endpoints
 * AC: @ui-plans-view ac-1
 */
export interface PlanSummary {
  _ulid: string;
  slugs: string[];
  title: string;
  status: string;
  created_at: string;
  approved_at?: string;
  completed_at?: string;
  derived_specs: string[];
  derived_tasks: string[];
  spec_count: number;
  task_count: number;
  task_progress: {
    total: number;
    completed: number;
    in_progress: number;
    pending: number;
    blocked: number;
  };
}

/**
 * Search result
 * AC: @api-contract ac-19
 * AC: @web-dashboard ac-24
 */
export interface SearchResult {
  type: 'item' | 'task' | 'inbox' | 'observation' | 'agent' | 'workflow' | 'convention';
  ulid: string;
  title: string;
  matchedFields: string[];
}

/**
 * Search response
 * AC: @api-contract ac-19
 * AC: @web-dashboard ac-24
 */
export interface SearchResponse {
  results: SearchResult[];
  total: number;
  showing: number;
}

/**
 * Validation result
 * AC: @api-contract ac-20
 */
export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  warnings: ValidationWarning[];
}

/**
 * Validation error
 */
export interface ValidationError {
  file: string;
  field: string;
  message: string;
  ref?: string;
}

/**
 * Validation warning
 */
export interface ValidationWarning {
  file: string;
  message: string;
  ref?: string;
}

/**
 * Alignment index stats
 * AC: @api-contract ac-21
 */
export interface AlignmentStats {
  total_specs: number;
  total_tasks: number;
  specs_without_tasks: number;
  tasks_without_specs: number;
  warnings: string[];
}

/**
 * Convention definition from meta manifest
 */
export interface Convention {
  _ulid: string;
  domain: string;
  rules: string[];
  examples?: Array<{ good: string; bad: string }>;
  validation?: {
    type: 'regex' | 'enum' | 'range' | 'prose';
    pattern?: string;
    message?: string;
    allowed?: string[];
    min?: number;
    max?: number;
    unit?: 'words' | 'chars' | 'lines';
  };
}

/**
 * Triage status lifecycle
 */
export type TriageStatus = 'pending' | 'triaged' | 'acted_on';

/**
 * Triage action types
 */
export type TriageAction = 'promote' | 'delete' | 'defer' | 'spec-gap' | 'duplicate';

/**
 * Triage record
 */
export interface TriageRecord {
  _ulid: string;
  inbox_ref: string;
  item_snapshot: string;
  status: TriageStatus;
  action?: TriageAction;
  reasoning?: string;
  decided_by?: string;
  evidence_refs: string[];
  override_reasoning?: string;
  override_by?: string;
  override_at?: string;
  acted_at?: string;
  result_ref?: string;
  created_at: string;
  updated_at?: string;
}

/**
 * Acceptance criterion with inheritance tracking
 */
export interface InheritedAC extends AcceptanceCriterion {
  _inherited_from: string;
}

/**
 * Exported task with resolved spec reference title
 */
export interface ExportedTask extends TaskDetail {
  spec_ref_title?: string;
}

/**
 * Exported spec item with nested hierarchy and inherited ACs.
 * Note: extends ItemDetail (acceptance_criteria required) because the JSON
 * snapshot always includes the field. The core export module uses Omit to
 * build from parser types where AC may not yet exist, but by the time data
 * reaches the web-ui via snapshot, AC is always present (at least as []).
 */
export interface ExportedItem extends ItemDetail {
  children?: ExportedItem[];
  inherited_acs?: InheritedAC[];
}

/**
 * Project metadata in a snapshot
 */
export interface ExportedProject {
  name: string;
  version?: string;
  description?: string;
}

/**
 * Validation result included in a snapshot
 */
export interface ExportedValidation {
  valid: boolean;
  errorCount: number;
  warningCount: number;
  errors: Array<{
    file: string;
    message: string;
    path?: string;
  }>;
  warnings: Array<{
    file: string;
    message: string;
  }>;
}

/**
 * Full kspec snapshot structure
 */
export interface KspecSnapshot {
  version: string;
  exported_at: string;
  project: ExportedProject;
  tasks: ExportedTask[];
  items: ExportedItem[];
  inbox: InboxItem[];
  session: SessionContext | null;
  observations: Observation[];
  agents: Agent[];
  workflows: Workflow[];
  conventions: Convention[];
  validation?: ExportedValidation;
}

