1634→  /** Number of context-iter-*.json files (iteration count) */
1635→  iteration_count: number;
1636→  /** Number of tasks completed during the session */
1637→  tasks_completed: number;
1638→}
1639→
1640→/**
1641→ * Count lines in events.jsonl without parsing JSON.
1642→ * Much faster than readEvents() for large files.
1643→ */
1644→async function countEventLines(
1645→  specDir: string,
1646→  sessionId: string,
1647→): Promise<number> {
1648→  const eventsPath = getSessionEventsPath(specDir, sessionId);
1649→  try {
1650→    const content = await fsPromises.readFile(eventsPath, "utf-8");
1651→    if (!content.trim()) return 0;
1652→    return content.trim().split("\n").length;
1653→  } catch {
1654→    return 0;
1655→  }
1656→}
1657→
1658→/**
1659→ * Count context-iter-*.json files for a session (iteration count).
1660→ */
1661→async function countIterations(
1662→  specDir: string,
1663→  sessionId: string,
1664→): Promise<number> {
1665→  const sessionDir = getSessionDir(specDir, sessionId);
1666→  try {
1667→    const entries = await fsPromises.readdir(sessionDir);
1668→    return entries.filter(
1669→      (e) => e.startsWith("context-iter-") && e.endsWith(".json"),
1670→    ).length;
1671→  } catch {
1672→    return 0;
1673→  }
1674→}
1675→
1676→/**
1677→ * Count task completions by scanning events for tool calls that invoke
1678→ * `kspec task complete` or `npm run dev -- task complete`.
1679→ *
1680→ * Handles multiple adapter formats:
1681→ * - claude-code-acp: rawInput.command is a string in tool_call_update events
1682→ * - claude-agent-acp: rawInput.command is a string in tool_call_update events
1683→ *   (initial tool_call event has empty rawInput {})
1684→ * - codex-acp: rawInput.command is an array ['/usr/bin/bash', '-lc', 'kspec task complete @ref']
1685→ *   in tool_call events; actual command is at index 2
1686→ *
1687→ * We use a fast substring check before JSON parsing for performance.
1688→ */
1689→async function countTaskCompletions(
1690→  specDir: string,
1691→  sessionId: string,
1692→): Promise<number> {
1693→  const eventsPath = getSessionEventsPath(specDir, sessionId);
1694→  try {
1695→    const content = await fsPromises.readFile(eventsPath, "utf-8");
1696→    if (!content.trim()) return 0;
1697→    const lines = content.trim().split("\n");
1698→    let count = 0;
1699→    for (const line of lines) {
1700→      // Quick substring pre-filter: only parse lines that might contain task complete commands
1701→      if (!line.includes("task complete")) continue;
1702→      try {
1703→        const event = JSON.parse(line);
1704→        const rawCommand = event?.data?.update?.rawInput?.command;
1705→        // Normalize: string (claude-*-acp) or array like [bash, -lc, cmd] (codex-acp)
1706→        const command =
1707→          typeof rawCommand === "string"
1708→            ? rawCommand
1709→            : Array.isArray(rawCommand) && rawCommand.length > 0
1710→              ? rawCommand[rawCommand.length - 1]
1711→              : undefined;
1712→        if (typeof command === "string" && /\btask complete\b/.test(command)) {
1713→          count++;
1714→        }
1715→      } catch {
1716→        // Skip unparseable lines
1717→      }
1718→    }
1719→    return count;
1720→  } catch {
1721→    return 0;
1722→  }
1723→}
