1725→/**
1726→ * Get a summary of a single session for list display.
1727→ *
1728→ * Gathers metadata and computes metrics lazily (only parses what's needed).
1729→ *
1730→ * @param specDir - The .kspec directory path
1731→ * @param sessionId - Session ID
1732→ * @returns Session summary or null if session doesn't exist
1733→ */
1734→export async function getSessionLogSummary(
1735→  specDir: string,
1736→  sessionId: string,
1737→): Promise<SessionLogSummary | null> {
1738→  const metadata = await getSession(specDir, sessionId);
1739→  if (!metadata) return null;
1740→
1741→  const [eventCount, iterationCount, tasksCompleted] = await Promise.all([
1742→    countEventLines(specDir, sessionId),
1743→    countIterationsBoundaryAware(specDir, sessionId),
1744→    countTaskCompletions(specDir, sessionId),
1745→  ]);
1746→
1747→  const startMs = new Date(metadata.started_at).getTime();
1748→  const endMs = metadata.ended_at
1749→    ? new Date(metadata.ended_at).getTime()
1750→    : Date.now();
1751→  const durationMs = endMs - startMs;
1752→
1753→  return {
1754→    id: metadata.id,
1755→    status: metadata.status,
1756→    agent_type: metadata.agent_type,
1757→    session_type: resolveSessionType(metadata),
1758→    task_id: metadata.task_id,
1759→    started_at: metadata.started_at,
1760→    ended_at: metadata.ended_at,
1761→    duration_ms: durationMs,
1762→    event_count: eventCount,
1763→    iteration_count: iterationCount,
1764→    tasks_completed: tasksCompleted,
1765→  };
1766→}
1767→
1768→/**
1769→ * Get summaries for all sessions.
1770→ *
1771→ * @param specDir - The .kspec directory path
1772→ * @returns Array of session summaries
1773→ */
1774→export async function getAllSessionLogSummaries(
1775→  specDir: string,
1776→): Promise<SessionLogSummary[]> {
1777→  const sessionIds = await listSessions(specDir);
1778→  const summaries = await Promise.all(
1779→    sessionIds.map((id) => getSessionLogSummary(specDir, id)),
1780→  );
1781→  return summaries.filter((s): s is SessionLogSummary => s !== null);
1782→}
1783→
1784→// ─── Context Snapshots ───────────────────────────────────────────────────────
1785→
1786→/**
1787→ * Save session context snapshot for a given iteration.
1788→ *
1789→ * This creates an audit trail of what context the agent saw at each iteration,
1790→ * useful for debugging and reviewing agent behavior.
1791→ *
1792→ * @param specDir - The .kspec directory path
1793→ * @param sessionId - Session ID
1794→ * @param iteration - Iteration number
1795→ * @param context - The session context data
1796→ */
1797→export async function saveSessionContext(
1798→  specDir: string,
1799→  sessionId: string,
1800→  iteration: number,
1801→  context: unknown,
1802→): Promise<void> {
1803→  const sessionDir = getSessionDir(specDir, sessionId);
1804→  const contextPath = getSessionContextPath(specDir, sessionId, iteration);
1805→
1806→  // Ensure session directory exists
1807→  await fsPromises.mkdir(sessionDir, { recursive: true });
1808→
1809→  // Write context snapshot as pretty JSON
1810→  const content = JSON.stringify(context, null, 2);
1811→  await fsPromises.writeFile(contextPath, content, "utf-8");

